import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易口訣義 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易口訣義 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"classics/koujueyi/028.md","filePath":"classics/koujueyi/028.md"}'),r={name:"classics/koujueyi/028.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>彖曰：大畜，剛健篤實輝光，日新其德。剛上而尚賢，能止健，大正也。「不家食吉」，養賢也。利涉大川，應乎天也。象曰：天在山中，大畜。君子以多識前言往行，以畜其德。</p><p>初九：有厲利已。</p><p>象曰：「有厲利已」，不犯災也。</p><p>九二：輿說輹。</p><p>象曰：「輿說輹」，中無尤也。</p><p>九三：良馬逐，利艱貞。曰閒輿衛，利有攸往。</p><p>象曰：「利有攸往」，上合志也。</p><p>六四：童牛之牿，元吉。</p><p>象曰：六四「元吉」，有喜也。</p><p>六五：豶豕之牙，吉。</p><p>象曰：六五之「吉」，有慶也。</p><p>上九：何天之衢，亨。</p><p>象曰：「何天之衢」，道大行也。</p><p>解讀</p><p>「大畜利貞」者，艮止於上，乾剛前進不得通，故曰「大畜」也。柔能制剛，非正不可，故曰「利貞」也。不家食吉，有大畜之財，常須養贍賢人，使賢德食祿，非食自家之食也。「利涉大川」者，豐財養賢，是合天之道，應人之心，故可濟涉大川，不懼沉溺也。象曰「天在山中，大畜」者，艮山上止乾，陽不得通，故曰「大畜」也。「君子以多識前言往行，以畜其德」者，君子識前代人言往哲之行，使多聞多見，以畜積而為己德也。</p><p>初九，有厲，利已。已，止也。初欲前進，遇四畜盛，若進即有危厲，若休已不進，即有所利，故曰「有厲利已」。</p><p>九二，輿說輹。處畜之盛，不可前進，進而不已，則輿說輹敗，不可以行。然九二有居中之德，不妄前進，豈有過尤哉？</p><p>九三，良馬逐，利艱貞。曰閒輿衛，利有攸往者，夫「大畜」者，先畜後通，今處乾之上，畜道見通，可以升進。以上九有尚賢之德，而不拒於九三，三可以乘其壯馬，馳騁而來，故曰「良馬逐」。途路近通而未全泰，宜艱固而守貞正，故曰「利艱貞」。「曰閒輿衛」者，閒，礙也，衛，護也。雖日日見有人閒礙於輿，此則人之助己，乃是防衛見護也。何衢既通，小為阻礙，故無妨攸往。</p><p>六四：童牛之牿，元吉。童牛，一歲之牛，其角如繭栗。處艮之下，是畜之首。畜道將盛，初既止而不進，故六四可以童牛之角而止牿於初，以柔制剛，以息強爭，非惟獲其大吉，而亦有喜慶也。</p><p>六五：豶豕之牙，吉者，豕牙，橫猾難制之物，謂九二也。九二前進，如豕之牙。五處畜盛而能制之，故豶制其牙使不前，能止強暴，非惟獲勝，乃得吉慶，故云「有慶」。</p><p>上九：何天之衢，亨者，處畜之極，何須更畜，途徑大通，無復為礙。衢者，四達之路。爾雅雲「四達謂之衢」是也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
